import React from "react";
import Lottie from "lottie-react";
import addTaskAnimation from "../assets/animations/add-task.json";
import completeTaskAnimation from "../assets/animations/complete-task.json";

function Dashboard() {
  return (
    <div className="dashboard-container">
      <h1 className="dashboard-title">Welcome to Nityo Dashboard</h1>

      <div className="dashboard-card">
        <Lottie animationData={addTaskAnimation} loop={true} style={{ height: 150 }} />
        <button className="action-btn">Add Task</button>
      </div>

      <div className="dashboard-card">
        <Lottie animationData={completeTaskAnimation} loop={false} style={{ height: 150 }} />
        <button className="action-btn">Complete Task</button>
      </div>
    </div>
  );
}

export default Dashboard;
